{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-nexusnv-github-sidebar",
  "version": "0.2.0",
  "description": "Project-level GitHub workbench for OpenCode V2: pull requests, issues, and worktree-backed sessions in the sidebar.",
  "type": "module",
  "license": "MIT",
  "author": "nexusnv",
  "homepage": "https://github.com/nexusnv/opencode-nexusnv-github-sidebar#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nexusnv/opencode-nexusnv-github-sidebar.git"
  },
  "bugs": {
    "url": "https://github.com/nexusnv/opencode-nexusnv-github-sidebar/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "github",
    "pull-requests",
    "issues",
    "sidebar",
    "tui"
  ],
  "packageManager": "bun@1.4.0",
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "engines": {
    "bun": ">=1.4.0"
  },
  "overrides": {
    "seroval": "1.6.3",
    "seroval-plugins": "1.6.3"
  },
  "exports": {
    ".": "./dist/index.js",
    "./tui": "./dist/tui.js",
    "./rpc": "./dist/rpc.js"
  },
  "files": [
    "dist/",
    "index.ts",
    "tui.tsx",
    "rpc.ts",
    "src/",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "build": "bun run scripts/build.ts",
    "prepack": "bun run build",
    "typecheck": "tsc --noEmit",
    "lint": "oxlint src test scripts index.ts tui.tsx rpc.ts",
    "lint:fix": "oxlint --fix src test scripts index.ts tui.tsx rpc.ts",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "test": "bun run build && bun test",
    "test:watch": "bun test --watch",
    "check": "bun run format:check && bun run lint && bun run typecheck && bun run test",
    "audit": "bun run scripts/audit.ts",
    "pack:check": "bun run build && bun run scripts/assert-pack.ts",
    "smoke:live": "bun run scripts/live-smoke.ts"
  },
  "dependencies": {
    "open": "11.0.4"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.8",
    "@opentui/solid": ">=0.6.8",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.1.4",
    "@opencode/theme": "2.1.4",
    "@opentui/core": "0.6.8",
    "@opentui/solid": "0.6.8",
    "@types/bun": "1.4.4",
    "@types/node": "24.12.2",
    "oxlint": "1.89.0",
    "prettier": "3.9.10",
    "solid-js": "1.9.15",
    "typescript": "5.9.3"
  }
}
